from pathlib import Path
import json, subprocess, shutil, html
HTML_NOTICE='<!-- Bar chart portions adapted from HyperFrames animated-bar-chart, Copyright 2026 HeyGen, Inc., Apache-2.0. Changed to five recorded input groups, actual CAD AUCs and Lumen styling. See licenses/HYPERFRAMES-LICENSE.txt and licenses/NOTICE.txt. -->\n'
R=Path(__file__).resolve().parent
chapters=json.loads((R/'chapters.json').read_text())
(R/'compositions').mkdir(exist_ok=True)
shutil.copyfile(R/'node_modules/gsap/dist/gsap.min.js',R/'assets/gsap.min.js')
(R/'frame.md').write_text('''# Lumen: evidence you can inspect\n\nThe film presents a working research application. Real UI captures are the focal object; large text on the left tells judges exactly what to inspect. Dark ink, pale text and mint match the application. Use generic system sans-serif and monospace, generous spacing, and one clear claim per chapter. Six separate compositions use hard cuts. No decorative patient imagery, simulated results, clinical claims or competition claims. English narration is locally generated and disclosed. Show named reference anatomy, a frozen validation diagram, exact SHAP reconstruction, independently refitted input profiles, observed errors and reproducibility.\n\nMotion: title settles once, information arrives as narration develops, and each chapter has a slow progress rule tied to duration. Captured interaction plays at its original speed, followed by an explicit still of its last recorded state. Charts use the registry animated-bar-chart growth recipe with actual data. No invented UI interactions.\n''')
(R/'storyboard.md').write_text('''# Demonstration sequence\n\n1. Inspectable estimates — actual heart rotation and vessel selection; generic reference anatomy limitation.\n2. Train, select, evaluate — 303 records, 242 development, 61 final; nested validation and outcome exclusion.\n3. An excluded development case — actual vessel selector; grouped interventional linear SHAP, full-fold reference, reconstruction and independent numerical verification.\n4. Evidence availability — actual profile selector; independently fitted models; CAD development AUC bars for 17/31/38/52/55 inputs. Registry animated-bar-chart adapted to five real values.\n5. Errors and final evaluation — actual reveal and threshold comparison; final AUC, confusion counts and limitations.\n6. Reproducible working submission — actual unlabelled input form; package content, CPU runtime and AI disclosure.\n\nAll chapter titles use explicit fromTo opacity/y entrance. Footage is real CUA browser screencast, not a mockup. Narration files are local Kokoro TTS. The required final local render is authorized by the user's instruction to complete the entire submission. Public upload remains account dependent.\n''')
CSS='''*{box-sizing:border-box;margin:0;padding:0}html,body{width:1920px;height:1080px;overflow:hidden;background:#0b141d;color:#edf5f6;font-family:sans-serif}#root{width:100%;height:100%;position:relative}.clip{position:absolute;inset:0}.film-bg{position:absolute;inset:0;background:#0b141d}.brand{position:absolute;left:70px;top:48px;font-size:34px;letter-spacing:-1px;font-weight:800;color:#78dfc9}.chapter{position:absolute;right:70px;top:57px;font-size:22px;letter-spacing:2px;color:#b7c9d4;font-family:monospace}.left{position:absolute;left:70px;top:150px;width:590px}.eyebrow{font-family:monospace;letter-spacing:2px;color:#78dfc9;font-size:24px;margin-bottom:25px}.title{font-size:68px;line-height:1.05;letter-spacing:-2.3px;font-weight:800;max-width:600px}.lede{font-size:31px;line-height:1.3;color:#c5d8e1;margin-top:30px}.points{margin-top:32px;display:grid;gap:24px}.point{border-left:4px solid #78dfc9;padding-left:20px;font-size:28px;line-height:1.32;color:#e1edf2}.point small{display:block;margin-top:8px;font-size:22px;color:#aec5d2;line-height:1.32}.capture{position:absolute;left:750px;top:135px;width:1100px;height:860px;border:1px solid #344c5d;background:#101b25;object-fit:contain}.capture-label{position:absolute;left:770px;top:103px;font-size:21px;letter-spacing:1px;font-family:monospace;color:#bed4df}.foot{position:absolute;left:70px;bottom:28px;font-size:20px;color:#b9cdd8;max-width:1600px}.progress{position:absolute;left:70px;bottom:13px;width:1780px;height:3px;background:#78dfc9;transform-origin:left center}.workflow{position:absolute;left:90px;top:340px;width:1740px;display:grid;grid-template-columns:repeat(4,1fr);gap:32px}.step{height:360px;border-top:4px solid #78dfc9;background:#14222e;padding:28px}.step .num{font-size:72px;font-weight:800;color:#78dfc9;margin-bottom:20px}.step h3{font-size:33px;line-height:1.15;margin-bottom:18px}.step p{font-size:27px;line-height:1.35;color:#cadce6}.wide-title{position:absolute;left:90px;top:150px;width:1700px;font-size:70px;letter-spacing:-2px;line-height:1.1}.wide-note{position:absolute;left:100px;top:755px;width:1660px;font-size:34px;line-height:1.35;color:#c7dce6}.code{font-family:monospace;font-size:25px;line-height:1.5;margin-top:30px;padding:20px;background:#14222e;color:#aee7d8}.metrics{margin-top:28px;display:grid;gap:16px}.metric{display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #344a5b;padding:9px 0;font-size:30px}.metric b{font-size:50px;color:#78dfc9}.metric small{font-size:20px;color:#bed3de}.hf-catalog-animated-bar-chart{width:590px;margin-top:36px}.hf-catalog-animated-bar-chart .bars{height:230px;display:grid;grid-template-columns:repeat(5,1fr);align-items:end;gap:18px}.hf-catalog-animated-bar-chart .bar{height:calc(var(--h)*var(--hf-grow,1));background:#78dfc9;border-radius:5px 5px 0 0;position:relative}.hf-catalog-animated-bar-chart .bar b{position:absolute;top:-35px;width:100%;text-align:center;font-size:23px;color:#edf5f6}.bar-labels{display:grid;grid-template-columns:repeat(5,1fr);gap:18px;margin-top:12px;font-size:19px;text-align:center;color:#ccdee7}.callout{margin-top:24px;font-size:24px;line-height:1.35;color:#d0e2eb}.math{margin-top:35px;font-family:monospace;font-size:30px;line-height:1.7;background:#14222e;padding:20px;color:#aae6d7}'''
starts=[]; cursor=0; durations=[]
for c in chapters:
    p=subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','json',str(R/f'assets/voice-{c["id"]}.wav')])
    duration=float(json.loads(p)['format']['duration'])+2.0
    starts.append(round(cursor,3));durations.append(duration);cursor+=duration
contents=[]
contents.append(('Make every estimate inspectable','Anatomy · measurements · evidence', '''<p class="lede">Four predictions connected to named coronary anatomy and the measurements behind them.</p><div class="points"><div class="point">CAD · LAD · LCX · RCA</div><div class="point">Rotate, zoom and select vessels<small>BodyParts3D reference geometry</small></div><div class="point">Generic anatomy<small>Colors do not locate plaque or lesions.</small></div></div>''','anatomy','Research demonstration · public development record · generic reference heart'))
contents.append(('Train, select, then evaluate','Frozen procedure · local CPU', '',None,'UCI extension dataset · all Cath, LAD, LCX and RCA outcomes excluded from inputs'))
contents.append(('Trace a real excluded case','Exact model explanation', '''<p class="lede">This record was excluded from fitting, calibration and threshold selection.</p><div class="math"><p>baseline + Σ contributions</p><p>= model log odds</p></div><div class="points"><div class="point">Grouped interventional linear SHAP<small>One-hot terms summed by raw feature</small></div><div class="point">Verified against SHAP<small>Maximum encoded term difference: 6.94 × 10⁻¹⁸</small></div><div class="point">Associations, without causal claims</div></div>''','anatomy','Reference = complete training-fold background · input correlations are not modeled'))
vals=[.828,.921,.937,.922,.926]
bars=''.join(f'<span class="bar" style="--h:{v*100}%"><b>{v:.3f}</b></span>' for v in vals)
contents.append(('What survives with fewer inputs?','Five independently refitted profiles',f'''<p class="lede">CAD development AUC under the same validation folds.</p><div class="hf-catalog-animated-bar-chart"><div class="bars">{bars}</div><div class="bar-labels"><span>History<div>17</div></span><span>+ Exam<div>31</div></span><span>+ ECG<div>38</div></span><span>+ Lab<div>52</div></span><span>+ Echo<div>55</div></span></div></div><p class="callout">Required inputs, predictions, colors, explanations and measured metrics update together.</p><p class="callout">Exploratory comparison; no claim about clinical test ordering or benefit.</p>''','profiles','Development evidence · same 242 records · no uniform gain from additional input groups'))
metrics=''.join(f'<div class="metric"><span>{name}<small> · FP {fp} / FN {fn}</small></span><b>{auc:.3f}</b></div>' for name,auc,fp,fn in [('CAD',.90826873385,7,3),('LAD',.8933333,8,1),('LCX',.7483660,20,4),('RCA',.7244444,19,6)])
contents.append(('Keep errors and tradeoffs visible','Final held-out evaluation · n = 61',f'''<p class="lede">AUC and errors at frozen research thresholds</p><div class="metrics">{metrics}</div><p class="callout">The case on screen reveals missed positive labels.</p><p class="callout">Small single-cohort test; wide conditional intervals. No clinical readiness claim.</p>''','errors','Final split evaluated once after the protocol freeze · thresholds selected from development data'))
contents.append(('A reproducible working submission','Portable models · no cloud inference', '''<p class="lede">New unlabelled inputs use four frozen models fitted on development data.</p><div class="points"><div class="point">Source + portable weights<small>Training code, fixed split, explanations and model evidence</small></div><div class="point">Six-page report + provenance<small>Real anatomy, licenses and honest limitations</small></div><div class="point">Runs on a local CPU<small>Python inference · Three.js browser view</small></div></div><p class="callout">AI assistance: OpenAI Codex. English narration: local Kokoro TTS.</p>''','new-input-final','Educational research application · no training GPU or cloud model API required'))
for i,(title,eyebrow,body,clip,foot) in enumerate(contents):
    id=f'chapter-{i+1:02d}'; dur=durations[i]
    head=f'<div class="film-bg"></div><div class="brand">Lumen</div><div class="chapter">TRACK A / {i+1:02d} OF 06</div>'
    if clip:
        cap=json.loads((R/f'assets/{clip}-capture.json').read_text()); cdur=float(cap['duration']) if 'duration' in cap else 12.0
        print(clip,cap.keys())
        bodyhtml=f'<div class="left"><div class="eyebrow">{eyebrow}</div><h1 class="title">{title}</h1>{body}</div><div class="capture-label">RECORDED APPLICATION</div><video id="{id}-video" class="clip capture" src="assets/{clip}.mp4" muted data-start="0" data-duration="{cdur}" data-track-index="1"></video><img id="{id}-still" class="clip capture" src="assets/{clip}-last.jpg" data-start="{cdur:.3f}" data-duration="{dur-cdur:.3f}" data-track-index="1"/>'
    else:
        bodyhtml=f'<h1 class="wide-title">{title}</h1><div class="workflow"><div class="step"><div class="num">303</div><h3>Public records</h3><p>Four outcomes removed from every input profile.</p></div><div class="step"><div class="num">242</div><h3>Development</h3><p>Five outer folds evaluate the entire procedure.</p></div><div class="step"><div class="num">3</div><h3>Inner folds</h3><p>Select regularization, weighting, calibration and thresholds.</p></div><div class="step"><div class="num">61</div><h3>Final evaluation</h3><p>Full-input protocol frozen before scoring this split.</p></div></div><div class="wide-note">Portable coefficients + scalers + imputers + encoders.<p class="code">CPU training → exported JSON → local Python inference</p></div>'
    script=f'''<script>{{ const tl=gsap.timeline({{paused:true}}); const a=(s,f,t,p)=>{{if(document.querySelector(s))tl.fromTo(s,f,t,p)}}; a('#{id} h1',{{opacity:0,y:25}},{{opacity:1,y:0,duration:.75,ease:'power3.out'}},.2); a('#{id} .lede,# {id} .eyebrow'.replace('# ', '#'),{{opacity:0}},{{opacity:1,duration:.6}},1); a('#{id} .point',{{opacity:0,y:16}},{{opacity:1,y:0,duration:.65,stagger:6,ease:'power3.out'}},5); a('#{id} .callout',{{opacity:0}},{{opacity:1,duration:.6,stagger:8}},23); a('#{id} .step',{{opacity:0,y:20}},{{opacity:1,y:0,duration:.8,stagger:7,ease:'power3.out'}},3); a('#{id} .wide-note',{{opacity:0}},{{opacity:1,duration:.6}},32); a('#{id} .hf-catalog-animated-bar-chart',{{'--hf-grow':0}},{{'--hf-grow':1,duration:1.2,ease:'power3.out'}},7); a('#{id} .progress',{{scaleX:0}},{{scaleX:1,duration:{dur:.3f},ease:'none'}},0); window.__timelines['{id}']=tl; }}</script>'''
    markup=f'''<!doctype html><html><head><meta charset="utf-8"/></head><body><template><style>#{id}{{position:absolute;inset:0;width:100%;height:100%;color:#edf5f6;font-family:sans-serif}}</style><div id="{id}" data-composition-id="{id}" data-width="1920" data-height="1080" data-duration="{dur:.3f}">{head}{bodyhtml}<p class="foot">{foot}</p><div class="progress"></div></div>{script}</template></body></html>'''
    (R/f'compositions/{id}.html').write_text(markup.replace('<head>', '<head>'+HTML_NOTICE,1) if i==3 else markup)
mounts=''.join(f'<div id="mount-{i+1:02d}" class="clip" data-composition-id="chapter-{i+1:02d}" data-composition-src="compositions/chapter-{i+1:02d}.html" data-start="{starts[i]:.3f}" data-duration="{durations[i]:.3f}" data-track-index="0" data-width="1920" data-height="1080"></div>' for i in range(6))
audio=''.join(f'<audio id="voice-{i+1:02d}" src="assets/voice-{i+1:02d}.wav" data-start="{starts[i]+.8:.3f}" data-duration="{durations[i]-2:.3f}" data-track-index="2"></audio>' for i in range(6))
(R/'index.html').write_text(f'<!doctype html><html lang="en"><head>{HTML_NOTICE}<meta charset="utf-8"/><script src="assets/gsap.min.js"></script><style>{CSS}</style></head><body><div id="root" data-composition-id="main" data-width="1920" data-height="1080" data-duration="{cursor:.3f}">{mounts}{audio}</div><script>window.__timelines["main"]=gsap.timeline({{paused:true}});</script></body></html>')
(R/'timeline-manifest.json').write_text(json.dumps({'duration':cursor,'chapters':[dict(id=c['id'],start=s,duration=d,title=c['title']) for c,s,d in zip(chapters,starts,durations)],'footage':'Real CUA browser screencasts at original speed, then held final captured frame','narration':'Local Kokoro af_heart speed 0.93, generated; no human narrator claimed'},indent=2)+'\n')
print('Total',cursor)
